package docked_service_access_lifecycle_supervisor.Docked_Service_Access_Lifecycle_Supervisor

import org.sireum._
import art._
import docked_service_access_lifecycle_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait IntentQualifier_Api {
  def id: Art.BridgeId
  def pilotIntent_Id : Art.PortId
  def qualifiedIntent_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualifiedIntent: Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type = $

  def put_qualifiedIntent(value : Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type) : Unit = {
    Contract(
      Modifies(qualifiedIntent),
      Ensures(
        qualifiedIntent == value
      )
    )
    Spec {
      qualifiedIntent = value
    }

    Art.putValue(qualifiedIntent_Id, Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class IntentQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val pilotIntent_Id : Art.PortId,
  val qualifiedIntent_Id : Art.PortId) extends IntentQualifier_Api

@datatype class IntentQualifier_Operational_Api (
  val id: Art.BridgeId,
  val pilotIntent_Id : Art.PortId,
  val qualifiedIntent_Id : Art.PortId) extends IntentQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var pilotIntent: Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type = $

  def get_pilotIntent() : Option[Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type] = {
    Contract(
      Ensures(
        Res == Some(pilotIntent)
      )
    )
    val value : Option[Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type] = Art.getValue(pilotIntent_Id) match {
      case Some(Docked_Service_Access_Lifecycle_Supervisor.PilotIntent_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port pilotIntent.  Expecting 'Docked_Service_Access_Lifecycle_Supervisor.PilotIntent_Payload' but received ${v}")
        None[Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type]()
      case _ => None[Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type]()
    }
    return value
  }
}
